(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.CartCore=factory();})(typeof globalThis!=='undefined'?globalThis:this,function(){
  const money=cents=>new Intl.NumberFormat('de-DE',{style:'currency',currency:'EUR'}).format(cents/100);
  const text=value=>String(value||'').replace(/[\r\n]+/g,' ').trim();
  function sanitizeCart(value,products){if(!Array.isArray(value))return [];return value.slice(0,30).filter(x=>x&&products.some(p=>p.id===x.id)).map(x=>({id:x.id,quantity:Math.min(20,Math.max(1,Math.floor(Number(x.quantity)||1))),budgetCents:Number.isSafeInteger(x.budgetCents)&&x.budgetCents>0&&x.budgetCents<=1000000?x.budgetCents:4500,color:text(x.color).slice(0,120)}));}
  function totals(cart,config,details={}){let goods=0,hasBudget=false;for(const x of cart){const product=config.products.find(p=>p.id===x.id);if(!product)continue;const fixed=Number.isInteger(product.priceCents)&&product.priceCents>0;goods+=(fixed?product.priceCents:x.budgetCents)*x.quantity;if(!fixed)hasBudget=true;}const card=details.card?config.cardCents:0;const delivery=details.fulfillment==='delivery'&&details.area==='hall'?config.deliveryCents:0;return{goods,card,delivery,total:goods+card+delivery,hasBudget,deliveryOnRequest:details.fulfillment==='delivery'&&details.area!=='hall'};}
  function message(cart,config,d={}){const t=totals(cart,config,d);const lines=['Guten Tag, Blumen Bierbach!','Ich möchte folgende Blumenauswahl unverbindlich anfragen:',''];cart.forEach(x=>{const p=config.products.find(p=>p.id===x.id);if(!p)return;const fixed=Number.isInteger(p.priceCents)&&p.priceCents>0;lines.push(`${x.quantity} × ${p.name} — ${fixed?'Preis':'Wunschbudget'} pro Stück: ${money(fixed?p.priceCents:x.budgetCents)}${x.color?' · Farbwunsch: '+text(x.color):''}`);});lines.push('',`Grußkarte: ${d.card?'Ja · '+money(config.cardCents):'Nein'}`);if(d.card)lines.push('Kartentext: '+(text(d.cardText)||'Wird persönlich abgestimmt.'));if(d.fulfillment==='delivery'){lines.push('',`Erhalt: Lieferung · ${d.area==='hall'?'Schwäbisch Hall · '+money(config.deliveryCents):'außerhalb Schwäbisch Halls · Kosten auf Anfrage'}`);if(d.deliveryMode==='location'){lines.push('Lieferort: Ort / Treffpunkt',`Ort / Orientierung: ${text(d.location)||'Ort wird persönlich abgestimmt.'}`);if(d.mapLink)lines.push('Kartenlink: '+text(d.mapLink));}else{lines.push('Lieferort: Adresse');const address=[text(d.street),[text(d.zip),text(d.city)].filter(Boolean).join(' ')].filter(Boolean).join(', ');lines.push('Adresse: '+(address||'Wird persönlich abgestimmt.'));}if(d.recipient)lines.push('Empfänger/in: '+text(d.recipient));if(d.recipientPhone)lines.push('Telefon Empfänger/in: '+text(d.recipientPhone));if(d.deliveryNote)lines.push('Lieferhinweis: '+text(d.deliveryNote));}else lines.push('','Erhalt: Abholung im Geschäft');lines.push('Wunschtermin: '+(text(d.date)||'Nach Absprache'));if(d.occasion)lines.push('Anlass: '+text(d.occasion));if(d.photoRequest)lines.push('Zusatzwunsch: Bitte nach Möglichkeit ein Foto vor der Übergabe/Lieferung senden (nach Absprache).');lines.push('',`${t.hasBudget?'Vorläufiger Gesamtbudget-Rahmen':'Vorläufige Gesamtsumme'}: ${money(t.total)}${t.deliveryOnRequest?' zzgl. Lieferkosten nach Absprache':''}`);lines.push('','Anfragende Person: '+text(d.sender),'Rückruf / Kontakt: '+text(d.phone));if(d.notes)lines.push('Weitere Wünsche: '+text(d.notes));lines.push('','Bitte bestätigen Sie Verfügbarkeit, endgültigen Preis und Termin. Vielen Dank!');return lines.join('\n');}
  return{money,sanitizeCart,totals,message};
});
